if (RD) {
const t0 = parseLocal(RD.start);
const step = RD.step_h * H;
const nowIdx = Math.min(RD.rates.length - 1, SIM.day * (24 / RD.step_h) - 1);
nowT = t0 + (nowIdx + 1) * step;
start = t0; duration = RD.duration; missionDay = SIM.day;
const inShelter = (i) => RD.shelter && i >= RD.shelter[0] && i < RD.shelter[1];
for (let i = 0; i <= nowIdx; i++) {
const loc = inShelter(i) ? L('Radiation shelter', 'Refugio contra radiación') : RD.locs_default;
recs.push({ t: t0 + i * step, kind: 'rate', value: RD.rates[i], unit: 'µGy/h', mag: 'abs', loc: loc, src: 'sim-dos', usable: true, idx: i });
recs.push({ t: t0 + (i + 1) * step, kind: 'cum', value: RD.cum[i], unit: 'mGy', mag: 'abs', loc: loc, src: 'sim-dos', usable: true, idx: i, hidden: true });
}
RD.unknown.forEach((u) => { if (u.i <= nowIdx) recs.push({ t: t0 + u.i * step + H, kind: 'rate', value: u.value, unit: '', mag: 'unknown', loc: RD.locs_default, src: 'sim-dos', usable: false, reason: 'unit' }); });
RD.eff.forEach((e) => { if (e.i <= nowIdx) recs.push({ t: t0 + (e.i + 1) * step, kind: 'eff', value: e.msv, unit: 'mSv', mag: 'eff', loc: '', src: 'sim-method', usable: true }); });
} else {
nowT = Date.now();
}
