let series = [];
if (F === '24h') series = wr.map((r) => ({ t: r.t, v: r.value * 24 / 1000, ev: inEvent(r.t) }));
else { const byDay = {}; wr.forEach((r) => { const k = Math.floor(r.t / D); (byDay[k] = byDay[k] || { s: 0, n: 0, ev: false, t: k * D }); byDay[k].s += r.value; byDay[k].n++; if (inEvent(r.t)) byDay[k].ev = true; });
series = Object.keys(byDay).sort((a, b) => a - b).map((k) => ({ t: byDay[k].t, v: byDay[k].s / byDay[k].n * 24 / 1000, ev: byDay[k].ev })); }
