const nice = (x) => { const c = [0.25, 0.5, 1, 2, 2.5, 5, 10, 20, 25, 50]; for (let k = 0; k < c.length; k++) if (c[k] * 4 >= x) return c[k] * 4; return Math.ceil(x); };
const ymaxA = nice(Math.max(env.hi * 1.6, normal.length ? Math.max.apply(null, normal) * 1.15 : 0));
