cdcTitle: L('Clinical reference for acute exposure (CDC)', 'Referencia clínica para exposición aguda (CDC)'), colDose: L('Absorbed dose', 'Dosis absorbida'), colMeaning: L('Interpretation', 'Interpretación'),
