yLabelC: L('Effective dose (mSv)', 'Dosis efectiva (mSv)'),
legCum: L('Career effective dose (mSv)', 'Dosis efectiva de carrera (mSv)'), legProj: L('Projection (estimate)', 'Proyección (estimación)'), careerLimitLabel: L('Career limit: under 600 mSv', 'Límite de carrera: menor de 600 mSv'),
