logTitle: L('Record a measurement', 'Registrar una medición'), fWhen: L('Date and time (UTC)', 'Fecha y hora (UTC)'), fType: L('Type', 'Tipo'), fValue: L('Value', 'Valor'), fUnit: L('Unit', 'Unidad'), fSrc: L('Source', 'Procedencia'), fLoc: L('Location (optional)', 'Ubicación (opcional)'), fSave: L('Save measurement', 'Guardar medición'),
typeRate: L('Dose rate', 'Tasa de dosis'), typeCum: L('Cumulative dose', 'Dosis acumulada'), typeEff: L('Effective dose (calculated)', 'Dosis efectiva (calculada)'), typeOrgan: L('Organ dose (model)', 'Dosis de órgano (modelo)'), unitUnknown: L('Unknown', 'Desconocida'),
